SORELLE = {
    "reception:registra": ("reception:importa", "reception:importa_modello", "reception:invito_gruppo",
                           "reception:partecipante_togli"),
    "reception:visita_scheda": ("reception:visita_allegati", "reception:visita_allegato"),
}
NOTA = "[RECEPTION_0012] copiato dalla pagina sorella"


def binding_avanti(apps, schema_editor):
    Binding = apps.get_model("core", "RoutePermissionBinding")
    for sorella, rotte in SORELLE.items():
        modello = Binding.objects.filter(route_name=sorella, is_active=True).order_by("-priority", "pk").first()
        if modello is None:
            continue
        for rotta in rotte:
            if Binding.objects.filter(route_name=rotta).exists():
                continue
            Binding.objects.create(
                route_name=rotta, path_pattern="", match_strategy=modello.match_strategy,
                permission_id=modello.permission_id, source_app="reception", priority=modello.priority,
                is_active=True, note=NOTA,
            )


def binding_indietro(apps, schema_editor):
    rotte = [r for gruppo in SORELLE.values() for r in gruppo]
    apps.get_model("core", "RoutePermissionBinding").objects.filter(route_name__in=rotte, note=NOTA).delete()


